_upgraded_buildings"":3,""max_seconds"":900,""no_rescue"":true,""reward"":240,""xp"":240,""origin"":""Challenge campaign 0.34""},{""id"":""ultimate_adaptation"",""title"":""Мастер адаптации"",""race"":""Ultimate Builder"",""opponent"":""Nerubian Swarm"",""description"":""Высший строитель против нерубов на сложном уровне. Не больше семи построек, две из них должны быть улучшены к победе."",""difficulty"":2,""max_buildings"":7,""min_upgraded_buildings"":2,""reward"":260,""xp"":260,""origin"":""Challenge campaign 0.34""}]"))if(!rows.Any(r=>(string)r["id"]==(string)row["id"]))rows.Add(row);
